import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Clash iPhone 与 iPad 版支持的代理协议","description":"Clash 支持的 21 类出站协议完整清单，包括 Shadowsocks、VMess、VLESS、Trojan、Hysteria2、TUIC、WireGuard 与 OpenVPN。","frontmatter":{"title":"Clash iPhone 与 iPad 版支持的代理协议","description":"Clash 支持的 21 类出站协议完整清单，包括 Shadowsocks、VMess、VLESS、Trojan、Hysteria2、TUIC、WireGuard 与 OpenVPN。","head":[["meta",{"name":"keywords","content":"Clash支持协议,Clash iOS Shadowsocks,VMess,VLESS,Trojan,Hysteria2,TUIC,WireGuard,OpenVPN,AnyTLS,Snell"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Clash 支持哪些代理协议？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Clash 支持 21 类出站协议：HTTP、SOCKS、Shadowsocks、ShadowsocksR、Snell、VMess、VLESS、Trojan、AnyTLS、Mieru、Sudoku、Hysteria、Hysteria2、TUIC、ShadowQUIC、WireGuard、Tailscale、SSH、MASQUE、TrustTunnel 与 OpenVPN。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"如何在 Clash 中使用 ss:// 等分享链接？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"可以把单节点分享链接或 Base64 节点列表整理为 mihomo YAML，或根据链接里的服务器、端口、凭据和协议参数在节点编辑器中添加。Profile 导入入口接受 HTTPS 订阅地址与完整 mihomo YAML。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"如何迁移其他 App 的配置？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"优先选择服务商提供的 mihomo YAML；来自 sing-box、Surge 或 Quantumult X 的节点可以根据协议参数在 Clash 中重新添加。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"开始使用 Clash 需要什么？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"准备一份你选择并信任的服务器配置或 HTTPS 订阅，即可导入 Clash。\\"}}]}"]]},"headers":[],"relativePath":"zh/guide/protocols.md","filePath":"zh/guide/protocols.md","lastUpdated":0}`),a={name:`zh/guide/protocols.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="clash-支持的代理协议" tabindex="-1">Clash 支持的代理协议 <a class="header-anchor" href="#clash-支持的代理协议" aria-label="Permalink to “Clash 支持的代理协议”">​</a></h1><p>Clash iPhone 与 iPad 版支持 <strong>21 类出站协议</strong>。可以通过 mihomo YAML、返回 mihomo YAML 的 HTTPS 订阅，或节点编辑器进行配置。</p><h2 id="完整协议清单" tabindex="-1">完整协议清单 <a class="header-anchor" href="#完整协议清单" aria-label="Permalink to “完整协议清单”">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>可用导入方式</th></tr></thead><tbody><tr><td>HTTP</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>SOCKS</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>Shadowsocks</td><td>mihomo YAML · 兼容订阅 · 手动添加</td></tr><tr><td>ShadowsocksR</td><td>mihomo YAML · 兼容订阅 · 手动添加</td></tr><tr><td>Snell</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>VMess</td><td>mihomo YAML · 兼容订阅 · 手动添加</td></tr><tr><td>VLESS</td><td>mihomo YAML · 兼容订阅 · 手动添加</td></tr><tr><td>Trojan</td><td>mihomo YAML · 兼容订阅 · 手动添加</td></tr><tr><td>AnyTLS</td><td>mihomo YAML · 兼容订阅 · 手动添加</td></tr><tr><td>Mieru</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>Sudoku</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>Hysteria</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>Hysteria2</td><td>mihomo YAML · 兼容订阅 · 手动添加</td></tr><tr><td>TUIC</td><td>mihomo YAML · 兼容订阅 · 手动添加</td></tr><tr><td>ShadowQUIC</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>WireGuard</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>Tailscale</td><td>mihomo YAML · 手动添加</td></tr><tr><td>SSH</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>MASQUE</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>TrustTunnel</td><td>mihomo YAML · 订阅 · 手动添加</td></tr><tr><td>OpenVPN</td><td>mihomo YAML · 订阅 · 手动添加</td></tr></tbody></table><h2 id="配置方式" tabindex="-1">配置方式 <a class="header-anchor" href="#配置方式" aria-label="Permalink to “配置方式”">​</a></h2><p>当前 iOS 客户端添加 Profile 时接受：</p><ul><li>HTTPS 订阅地址，且返回内容必须是有效的 mihomo YAML；</li><li><code>.yaml</code> 或 <code>.yml</code> 配置文件；</li><li>剪贴板中的完整 mihomo YAML；</li><li>包含 HTTPS 订阅地址的二维码。</li></ul><p>对于 <code>ss://</code>、<code>ssr://</code>、<code>vmess://</code> 等单节点分享链接，以及 Base64 节点列表，可以先整理为 mihomo YAML，或在节点编辑器中按服务器、端口、凭据和协议参数添加。</p><h2 id="从其他-app-迁移节点" tabindex="-1">从其他 App 迁移节点 <a class="header-anchor" href="#从其他-app-迁移节点" aria-label="Permalink to “从其他 App 迁移节点”">​</a></h2><p>Clash 以 mihomo YAML 作为配置格式。迁移 sing-box JSON、Surge Profile 或 Quantumult X 配置时，优先获取 mihomo 订阅，或根据原节点的协议参数在 Clash 中重新添加。</p><p>各品牌的推荐迁移方式请参阅<a href="/clash.md/zh/guide/compatibility">兼容性说明</a>。</p><h2 id="配置要点" tabindex="-1">配置要点 <a class="header-anchor" href="#配置要点" aria-label="Permalink to “配置要点”">​</a></h2><ul><li>使用你选择并信任的服务器、凭据与协议参数。</li><li>让 TLS、传输方式、混淆、UDP 与认证选项和服务器保持一致。</li><li>按照协议支持的传输方式与 UDP 模式完成配置。</li><li>保存后运行延迟测试与实际连接测试。</li></ul><h2 id="常见问答" tabindex="-1">常见问答 <a class="header-anchor" href="#常见问答" aria-label="Permalink to “常见问答”">​</a></h2><h3 id="clash-支持-shadowsocksr-吗" tabindex="-1">Clash 支持 ShadowsocksR 吗？ <a class="header-anchor" href="#clash-支持-shadowsocksr-吗" aria-label="Permalink to “Clash 支持 ShadowsocksR 吗？”">​</a></h3><p>支持。可以通过 mihomo YAML、返回 mihomo YAML 的兼容订阅，或根据 <code>ssr://</code> 链接中的参数在节点编辑器添加。</p><h3 id="clash-支持-wireguard、openvpn-与-tailscale-吗" tabindex="-1">Clash 支持 WireGuard、OpenVPN 与 Tailscale 吗？ <a class="header-anchor" href="#clash-支持-wireguard、openvpn-与-tailscale-吗" aria-label="Permalink to “Clash 支持 WireGuard、OpenVPN 与 Tailscale 吗？”">​</a></h3><p>支持，它们均可作为出站类型使用。地址、路由、凭据及其他必填项需要正确配置。</p><h3 id="clash-支持-hysteria2、tuic-与-anytls-吗" tabindex="-1">Clash 支持 Hysteria2、TUIC 与 AnyTLS 吗？ <a class="header-anchor" href="#clash-支持-hysteria2、tuic-与-anytls-吗" aria-label="Permalink to “Clash 支持 Hysteria2、TUIC 与 AnyTLS 吗？”">​</a></h3><p>支持。三者均可通过 mihomo YAML、返回 mihomo YAML 的兼容订阅，或节点编辑器添加。</p><h3 id="clash-支持-surge-使用的-snell-服务器吗" tabindex="-1">Clash 支持 Surge 使用的 Snell 服务器吗？ <a class="header-anchor" href="#clash-支持-surge-使用的-snell-服务器吗" aria-label="Permalink to “Clash 支持 Surge 使用的 Snell 服务器吗？”">​</a></h3><p>支持。可以在 Clash 中配置兼容的 Snell 服务器，并用 mihomo YAML 重新建立对应的策略组与规则。</p><h3 id="iphone-与-ipad-支持的协议相同吗" tabindex="-1">iPhone 与 iPad 支持的协议相同吗？ <a class="header-anchor" href="#iphone-与-ipad-支持的协议相同吗" aria-label="Permalink to “iPhone 与 iPad 支持的协议相同吗？”">​</a></h3><p>相同。Clash 是 iOS/iPadOS 通用 App，两种设备使用同一套 Hako 数据面。</p>`,24)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};